#include <algorithm>
#include <cstdint>
#include <functional>
#include <iostream>
#include <limits>
#include <queue>
#include <utility>
#include <vector>
int main(){int n,m;std::cin>>n>>m;using I=std::int64_t;using E=std::pair<I,int>;std::vector<std::vector<E>>g(n);while(m--){int a,b;I w;std::cin>>a>>b>>w;--a;--b;g[a].push_back({w,b});g[b].push_back({w,a});}I ans=std::numeric_limits<I>::max();for(int s=0;s<n;++s){std::vector<I>d(n,std::numeric_limits<I>::max());std::priority_queue<E,std::vector<E>,std::greater<E>>q;d[s]=0;q.push({0,s});while(!q.empty()){auto [dist,u]=q.top();q.pop();if(dist!=d[u])continue;for(auto [w,v]:g[u])if(dist+w<d[v]){d[v]=dist+w;q.push({d[v],v});}}ans=std::min(ans,*std::max_element(d.begin(),d.end()));}std::cout<<ans<<'\n';}

